ALTER TABLE bounties DROP CONSTRAINT bounty_status_check;
ALTER TABLE bounties ADD CONSTRAINT bounty_status_check CHECK(status IN ('OPEN','CANCELLED','CAPTURING','FUNDED','NEEDS_REVIEW','AWAITING_CLAIM','PAYING','PAID','REFUNDING'));
ALTER TABLE action_tokens DROP CONSTRAINT action_kind_check;
ALTER TABLE action_tokens ADD CONSTRAINT action_kind_check CHECK(action IN ('cancel_draft','fund','approve','cancellation_review'));
CREATE TABLE cancellation_requests (
 id bigserial PRIMARY KEY,bounty_id bigint NOT NULL REFERENCES bounties(id),requester_id bigint NOT NULL,funder_id bigint NOT NULL,claimants jsonb NOT NULL,next_reconcile_at timestamptz NOT NULL DEFAULT now(),reason_category text NOT NULL,reason text NOT NULL,links jsonb NOT NULL,notice_hours integer NOT NULL CHECK(notice_hours=72),status text NOT NULL DEFAULT 'NOTICE' CHECK(status IN ('NOTICE','REVIEW','APPROVED','DENIED','SUPERSEDED','EXECUTING','COMPLETED')),notice_comment_id text,notice_published_at timestamptz,notice_ends_at timestamptz,evidence_version integer NOT NULL DEFAULT 0,evidence_hash text,reviewer_id bigint,review_reason text,next_update_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),CHECK((notice_published_at IS NULL AND notice_ends_at IS NULL) OR notice_ends_at=notice_published_at+interval '72 hours')
);
CREATE UNIQUE INDEX one_active_cancellation ON cancellation_requests(bounty_id) WHERE status IN ('NOTICE','REVIEW','APPROVED','EXECUTING');
CREATE TABLE cancellation_evidence(id bigserial PRIMARY KEY,request_id bigint NOT NULL REFERENCES cancellation_requests(id),version integer NOT NULL,hash text NOT NULL,bundle jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(request_id,version));
CREATE TABLE cancellation_decisions(id bigserial PRIMARY KEY,request_id bigint NOT NULL REFERENCES cancellation_requests(id),evidence_version integer NOT NULL,actor_id bigint NOT NULL,decision text NOT NULL CHECK(decision IN ('approve','deny','hold')),reason text NOT NULL,assessments jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE refund_intents(id bigserial PRIMARY KEY,request_id bigint NOT NULL REFERENCES cancellation_requests(id),bounty_id bigint NOT NULL REFERENCES bounties(id),evidence_version integer NOT NULL,bounty_version integer NOT NULL,prior_status text NOT NULL CHECK(prior_status IN ('FUNDED','NEEDS_REVIEW')),capture_id text NOT NULL,amount_cents integer NOT NULL CHECK(amount_cents>0),request_key text NOT NULL UNIQUE,status text NOT NULL DEFAULT 'RESERVED' CHECK(status IN ('RESERVED','ABORTED_UNSENT','MAY_HAVE_SUBMITTED','IN_FLIGHT','SETTLED_OK','SETTLED_FAIL')),boundary_at timestamptz,safe_retry_until timestamptz,provider_id text UNIQUE,attention text,next_reconcile_at timestamptz NOT NULL DEFAULT now(),created_at timestamptz NOT NULL DEFAULT now(),CHECK(status NOT IN ('MAY_HAVE_SUBMITTED','IN_FLIGHT','SETTLED_OK','SETTLED_FAIL') OR boundary_at IS NOT NULL));
CREATE UNIQUE INDEX one_committed_refund ON refund_intents(bounty_id) WHERE status <> 'ABORTED_UNSENT';
CREATE FUNCTION protect_cancellation_history() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Cancellation evidence and decisions are immutable'; END $$;
CREATE TRIGGER immutable_cancellation_evidence BEFORE UPDATE OR DELETE ON cancellation_evidence FOR EACH ROW EXECUTE FUNCTION protect_cancellation_history();
CREATE TRIGGER immutable_cancellation_decisions BEFORE UPDATE OR DELETE ON cancellation_decisions FOR EACH ROW EXECUTE FUNCTION protect_cancellation_history();
CREATE FUNCTION protect_refund_identity() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF TG_OP='DELETE' OR ROW(NEW.request_id,NEW.bounty_id,NEW.evidence_version,NEW.bounty_version,NEW.prior_status,NEW.capture_id,NEW.amount_cents,NEW.request_key) IS DISTINCT FROM ROW(OLD.request_id,OLD.bounty_id,OLD.evidence_version,OLD.bounty_version,OLD.prior_status,OLD.capture_id,OLD.amount_cents,OLD.request_key) THEN RAISE EXCEPTION 'Refund identity is immutable'; END IF;
 IF OLD.boundary_at IS NOT NULL AND (NEW.boundary_at IS DISTINCT FROM OLD.boundary_at OR NEW.safe_retry_until IS DISTINCT FROM OLD.safe_retry_until OR NEW.status IN ('RESERVED','ABORTED_UNSENT')) THEN RAISE EXCEPTION 'Refund submission boundary is irreversible'; END IF;
 RETURN NEW; END $$;
CREATE TRIGGER immutable_refund_identity BEFORE UPDATE OR DELETE ON refund_intents FOR EACH ROW EXECUTE FUNCTION protect_refund_identity();
